using namespace Gdiplus;
namespace fs=std::filesystem;
static CLSID png;
static std::string guidString(const GUID&g){char b[64];sprintf_s(b,"%08lx-%04x-%04x-%02x%02x-%02x%02x%02x%02x%02x%02x",g.Data1,g.Data2,g.Data3,g.Data4[0],g.Data4[1],g.Data4[2],g.Data4[3],g.Data4[4],g.Data4[5],g.Data4[6],g.Data4[7]);return b;}
static void bounded(UINT w,UINT h){if(!w||!h||w>4096||h>4096||(unsigned long long)w*h>16777216)throw std::runtime_error("image dimensions outside reference bound");}
static void pixels(Bitmap&b,const fs::path&dir,const std::string&stem,std::ostream&o){UINT w=b.GetWidth(),h=b.GetHeight();bounded(w,h);Status saved=b.Save((dir/(stem+".png")).c_str(),&png,NULL);std::ofstream raw(dir/(stem+".rgba"),std::ios::binary);Status status=Ok;unsigned long long count=0,nonwhite=0,nonzeroalpha=0;int x0=(int)w,y0=(int)h,x1=-1,y1=-1;for(UINT y=0;y<h&&status==Ok;y++)for(UINT x=0;x<w;x++){Color c;status=b.GetPixel(x,y,&c);if(status!=Ok)break;unsigned char v[]={c.GetR(),c.GetG(),c.GetB(),c.GetA()};raw.write((char*)v,4);count++;if(v[3])nonzeroalpha++;if(v[0]!=255||v[1]!=255||v[2]!=255){nonwhite++;x0=std::min(x0,(int)x);y0=std::min(y0,(int)y);x1=std::max(x1,(int)x);y1=std::max(y1,(int)y);}}o<<"{\"png\":\""<<stem<<".png\",\"rgba\":\""<<stem<<".rgba\",\"width\":"<<w<<",\"height\":"<<h<<",\"saveStatus\":"<<saved<<",\"getPixelStatus\":"<<status<<",\"capturedPixels\":"<<count<<",\"nonwhitePixels\":"<<nonwhite<<",\"nonzeroAlphaPixels\":"<<nonzeroalpha<<",\"nonwhiteBounds\":["<<x0<<","<<y0<<","<<x1<<","<<y1<<"]}";}
static bool pinnedLoad(Bitmap&b,std::ostream&o){GUID raw={};Status rawStatus=b.GetRawFormat(&raw);Status last=b.GetLastStatus();o<<"{\"rawFormatStatus\":"<<rawStatus<<",\"afterRawFormatLastStatus\":"<<last<<",\"rawFormat\":\""<<guidString(raw)<<"\"}";return last==Ok;}
static void draw(const fs::path&path,const fs::path&dir,const std::string&stem,bool picture,bool transparent,std::ostream&o){Bitmap b(path.c_str(),FALSE);o<<"{\"load\":";bool loaded=pinnedLoad(b,o);if(loaded){UINT w=b.GetWidth(),h=b.GetHeight();bounded(w,h);Bitmap canvas(w,h,PixelFormat32bppARGB);canvas.SetResolution(96,96);Status drawStatus,interpolation=Ok,offset=Ok,wrap=Ok;{Graphics g(&canvas);g.Clear(transparent?Color(0,0,0,0):Color(255,255,255,255));ImageAttributes attr;if(picture){interpolation=g.SetInterpolationMode(InterpolationModeDefault);g.SetPixelOffsetMode(PixelOffsetModeHighQuality);offset=g.SetPixelOffsetMode(PixelOffsetModeHalf);wrap=attr.SetWrapMode(WrapModeTileFlipXY);}drawStatus=g.DrawImage(&b,Rect(0,0,(INT)w,(INT)h),0,0,(INT)w,(INT)h,UnitPixel,picture?&attr:NULL);}o<<",\"interpolationStatus\":"<<interpolation<<",\"pixelOffsetStatus\":"<<offset<<",\"wrapStatus\":"<<wrap<<",\"drawImageStatus\":"<<drawStatus<<",\"pixels\":";pixels(canvas,dir,stem,o);}o<<"}";}
static void inspect(const fs::path&path,const fs::path&dir,std::ostream&o){std::string name=path.stem().string();o<<"{\"name\":\""<<name<<"\",\"file\":\""<<path.filename().string()<<"\",\"constructorDiagnosticStatus\":";{Bitmap diagnostic(path.c_str(),FALSE);o<<diagnostic.GetLastStatus();}Bitmap b(path.c_str(),FALSE);o<<",\"pinnedLoad\":";bool loaded=pinnedLoad(b,o);if(loaded){UINT w=b.GetWidth(),h=b.GetHeight();bounded(w,h);RectF bounds;Unit unit=UnitWorld;Status bs=b.GetBounds(&bounds,&unit);o<<",\"imageType\":"<<b.GetType()<<",\"width\":"<<w<<",\"height\":"<<h<<",\"dpi\":["<<b.GetHorizontalResolution()<<","<<b.GetVerticalResolution()<<"],\"boundsStatus\":"<<bs<<",\"boundsUnit\":"<<(int)unit<<",\"bounds\":["<<bounds.X<<","<<bounds.Y<<","<<bounds.Width<<","<<bounds.Height<<"],\"directIntrinsicPixels\":";pixels(b,dir,name+"-intrinsic",o);o<<",\"plainNaturalWhite\":";draw(path,dir,name+"-plain-white",false,false,o);o<<",\"pictureNaturalWhite\":";draw(path,dir,name+"-picture-white",true,false,o);o<<",\"pictureNaturalTransparent\":";draw(path,dir,name+"-picture-transparent",true,true,o);}o<<"}";}
int main(int argc,char**argv){if(argc!=3)return 2;ULONG_PTR token;GdiplusStartupInput init;if(GdiplusStartup(&token,&init,NULL)!=Ok)return 3;int result=0;try{UINT count,size;GetImageEncodersSize(&count,&size);std::vector<BYTE>buf(size);GetImageEncoders(count,size,(ImageCodecInfo*)buf.data());bool found=false;for(UINT i=0;i<count;i++){auto&e=((ImageCodecInfo*)buf.data())[i];if(wcscmp(e.MimeType,L"image/png")==0){png=e.Clsid;found=true;}}if(!found)throw std::runtime_error("PNG encoder");fs::path input=argv[1],output=argv[2];fs::create_directories(output);std::ofstream o(output/"picture-bitmap16.json");o<<"{\"schema\":1,\"consumer\":\"Pinned Picture.cpp418 Bitmap(filename,FALSE), GetRawFormat, GetLastStatus, natural width/height; drawing547-556 Bitmap*, PixelOffsetHalf, WrapTileFlipXY, sourceUnitPixel\",\"cases\":[";bool first=true;for(auto&e:fs::directory_iterator(input))if(e.path().extension()==L".wmf"||e.path().extension()==L".emf"){if(!first)o<<",";first=false;fs::copy_file(e.path(),output/e.path().filename(),fs::copy_options::overwrite_existing);inspect(e.path(),output,o);}o<<"]}";if(!o)throw std::runtime_error("report write");}catch(const std::exception&e){std::cerr<<e.what()<<"\n";result=1;}GdiplusShutdown(token);return result;}
